// The hub's words in every language it speaks (hub.js reads these; pages-i18n.js has the data pages').
// One convention for every ZETAPHY app: these 8 codes, in this menu order; English is the default,
// a stored code from the set is kept, anything else falls back to English, and so does any missing key.

/** [code, native name], in menu order. */
export const LANGS = [['en', 'English'], ['zh', '中文'], ['es', 'Español'], ['ko', '한국어'], ['ja', '日本語'], ['ru', 'Русский'], ['vi', 'Tiếng Việt'], ['th', 'ไทย']];
export const LANG_CODES = LANGS.map(([c]) => c);
/** A stored / requested language -> one of LANG_CODES (English for anything else). */
export const pickLang = (v) => (LANG_CODES.includes(v) ? v : 'en');
/** The Intl locale for dates (English dates as day/month/year). */
export const locale = (l) => (l === 'en' ? 'en-GB' : pickLang(l));

/** table[lang] with table.en underneath, key by key (arrays by index, functions as is), so nothing shows a raw key. */
export function withFallback(table, l) {
  const merge = (base, over) => {
    if (over === undefined || over === null) return base;
    if (Array.isArray(base)) return base.map((b, i) => merge(b, over[i]));
    if (base && typeof base === 'object') return Object.fromEntries(Object.keys(base).map((k) => [k, merge(base[k], over[k])]));
    return over;
  };
  return merge(table.en, l === 'en' ? undefined : table[l]);
}

